from pathlib import Path
import xml.etree.ElementTree as E
for pmc in ('PMC13581591', 'PMC13581617','PMC13664187'):
 p=Path('data/papers')/(pmc+'.xml'); root=E.parse(p).getroot()
 print(pmc, 'bibliography',len(root.findall('.//back/ref-list/ref')))
 if pmc=='PMC13581591':
  for x in root.findall('.//p'):
   t=''.join(x.itertext())
   if 'CDK6' in t and any(v in t for v in ('0.44','0.520','0.640','abemaciclib')): print(t)
 if pmc=='PMC13664187':
  print('final ref',''.join(root.findall('.//back/ref-list/ref')[-1].itertext()))
